class Solution {
public:
    long long maxTaxiEarnings(int n, vector<vector<int>>& rides) {
        vector<vector<pair<int,int>>> endAt(n + 1);
        for (auto& r : rides) {
            endAt[r[1]].push_back({r[0], r[2]});
        }
        vector<long long> dp(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            dp[i] = dp[i - 1];
            for (auto& pr : endAt[i]) {
                long long earn = dp[pr.first] + (long long)(i - pr.first + pr.second);
                if (earn > dp[i]) dp[i] = earn;
            }
        }
        return dp[n];
    }
};
